&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Good knowledge of AS 9100:2016 and ISO 9001:2015 and having Internal Auditor certification &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
