&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;bringst&amp;nbsp;4–6 Jahre&amp;nbsp;fundierte&amp;nbsp;Berufserfahrung&amp;nbsp;als&amp;nbsp;Brand-&amp;nbsp;oder&amp;nbsp;Marketing Manager&amp;nbsp;im&amp;nbsp;FMCG- /&amp;nbsp;Konsumgüterbereich&amp;nbsp;mit.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Gerne aus dem Bereich Food &amp;amp; Beverage&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
