&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;trackst&amp;nbsp;Markenmetriken&amp;nbsp;(Awareness, Equity, Engagement)&amp;nbsp;sowie&amp;nbsp;Kampagnen-KPIs und&amp;nbsp;nutzt&amp;nbsp;die&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;se&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Daten für eine kontinuierliche Optimierung&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du arbeitest eng mit crossfunktionalen Teams zusammen, um ein konsistentes Markenerlebnis im D2C-Bereich, Pureplay und am Point of Sale &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;zu garantieren&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;TextRun SCXW22428633 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;Du&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;stimmst&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;dich&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;eng&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;mit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;den&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;lokalen&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;Commercial-Teams ab, um die&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;Marketingaktivitäten&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;perfekt&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;auf die Markt- und&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;Vertriebsziele&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22428633 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW22428633 BCX0&quot;&gt;auszurichten&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Deine&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Erfahrung&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;&amp;amp; Skills&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:281,&amp;quot;335559739&amp;quot;:281}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;bringst&amp;nbsp;4–6 Jahre&amp;nbsp;fundierte&amp;nbsp;Berufserfahrung&amp;nbsp;als&amp;nbsp;Brand-&amp;nbsp;oder&amp;nbsp;Marketing Manager&amp;nbsp;im&amp;nbsp;FMCG- /&amp;nbsp;Konsumgüterbereich&amp;nbsp;mit.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Gerne aus dem Bereich Food &amp;amp; Beverage&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;hast&amp;nbsp;nachweisbare&amp;nbsp;Erfahrung&amp;nbsp;in der&amp;nbsp;Führung&amp;nbsp;oder&amp;nbsp;Betreuung&amp;nbsp;eine&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;r&amp;nbsp;oder&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;mehrerer&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Marken in&amp;nbsp;der Schweiz mit Umsätzen&amp;nbsp;von&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;mindestens&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;50 Mio&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;. CHF&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du&amp;nbsp;besitzt&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;fundierte Erfahrung&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;in der Steuerung eines&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;D2C-Business&amp;nbsp;sowie in der Steuerung von&amp;nbsp;Omnichannel-Kampagnen (inkl. Mass Media, Influencer Marketing&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Social Media wie TikTok und Meta&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, sowie Point of Sale + Pureplay&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;)&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du zeichnest dich durch eine starke Hands-on-Mentalität, ausgeprägte Fähigkeiten im Projektmanagement und echte Lust auf crossfunktionale Zusammenarbeit aus&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du hast ein strategisches, kreatives und datengetriebenes Mindset und gehst sicher mit digitalen Marketing-Tools um&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du hast verhandlungssichere Deutsch- (Schweizerdeutsch) sowie fließende Französischkenntnisse und nutzt Englisch sicher für unsere interne Kommunikation&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;Warum wir?&amp;nbsp;&lt;/h3&gt;
&lt;p data-start=&quot;258&quot; data-end=&quot;599&quot;&gt;Bei The Quality Group arbeiten über 1.200 Menschen mit einer gemeinsamen Mission: Ernährung neu zu denken - gesünder, smarter und mit echtem Mehrwert für die Community.&lt;br data-start=&quot;434&quot; data-end=&quot;437&quot;&gt;Wir glauben an Teamgeist, Eigenverantwortung und den Mut, Grenzen zu verschieben. Dabei zählt jeder Beitrag, unabhängig vom Standort oder Bereich.&lt;br&gt;Je nachdem, wo du bei uns einsteigst, erwarten dich unterschiedliche Benefits, unter anderem:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Attraktive Mitarbeiterrabatte auf Produkte von ESN &amp;amp; More&lt;/li&gt;
&lt;li&gt;Flexible Arbeitszeiten &amp;amp; Homeoffice-Möglichkeiten&lt;/li&gt;
&lt;li&gt;Zuschüsse zu Mobilität &amp;amp; Fitness (z. B. Wellpass, Deutschlandticket)&lt;/li&gt;
&lt;li&gt;Betriebliche Altersvorsorge&lt;/li&gt;
&lt;li&gt;Workation-Optionen und mehr&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;981&quot; data-end=&quot;1212&quot;&gt;Im Bewerbungsprozess erfährst du, welche Vorteile dich an deinem Standort konkret erwarten und was es heißt, Teil von &lt;strong data-start=&quot;1101&quot; data-end=&quot;1108&quot;&gt;TQG&lt;/strong&gt; zu sein: Ein Unternehmen, das mit Leidenschaft, Qualität und Mut die Zukunft von Ernährung gestaltet.&lt;/p&gt;
&lt;p data-start=&quot;981&quot; data-end=&quot;1212&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;Über uns&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;The Quality Group (TQG) ist ein innovativer Anbieter von Sporternährungsprodukten und vereint seit 2021 die erfolgreichen Marken ESN und More Nutrition. &lt;br&gt;&lt;br&gt;ESN ist seit 2004 deutscher Marktführer für Sporternährung und bietet Produkte wie Proteinpulver, Riegel und Supplements, die auf ambitionierte Fitnessziele ausgerichtet sind. More Nutrition, gegründet 2017, steht für gesunde, zuckerreduzierte Ernährungsprodukte und bietet Lösungen für bewusste Ernährung und Gewichtsmanagement – ohne Verzicht. &lt;br&gt;&lt;br&gt;Die Vision von TQG ist es, Menschen dabei zu unterstützen, die beste Version ihrer selbst zu werden. Mit Leidenschaft und Innovationskraft entwickelt das Unternehmen hochwertige Produkte, die Gesundheit, Leistung und Lebensfreude fördern. Mit einer agilen Unternehmenskultur und spannenden Karrieremöglichkeiten ist TQG nicht nur für Kunden, sondern auch für Mitarbeitende ein starker Partner. &amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;strong&gt;Das sind wir – The Quality Group – nice to meet you! Now it’s your turn!&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Wir freuen uns auf deine Bewerbung! Unabhängig von Geschlecht, Alter, Herkunft oder Identität – bei uns zählt, wer du bist und was du einbringst. Werde Teil unseres Teams und wachse mit uns.&amp;nbsp;&lt;/p&gt;Find more English Speaking Jobs in Switzerland on Arbeitnow

&lt;p&gt;We are looking for passionate technologists to join our Pre-Sales organization to ensure that our growth is grounded and guided by strong technical alignment with our platform and the needs of our customers.&lt;/p&gt;
&lt;p&gt;MongoDB Pre-Sales Solution Architects are responsible for guiding our customers and users to design and build reliable, scalable systems using our data platform. Our team is made up of seasoned technical sales professionals, software architects, entrepreneurs, and developers who take direct responsibility for customer success, including the design of their software, deployment, and operations. You&#39;ll work closely with our sales executives, helping customers solve business problems by leveraging our solutions, playing a key role in winning deals and driving the business forward. You&#39;ll be a trusted advisor to a wide range of users from startups to the world&#39;s largest enterprise IT organizations.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role will be based remotely in Switzerland.&lt;/p&gt;
&lt;h3&gt;As an ideal candidate, you will have:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Ideally 8 to 11 years of related experience in a customer facing role, with 5 to 7 years of experience in pre-sales with enterprise software&lt;/li&gt;
&lt;li&gt;Minimum of 3 years experience with modern scripting languages (e.g. Python, Node.js, SQL) and/or popular programming languages (e.g. C/C++, Java, C#) in a professional capacity&lt;/li&gt;
&lt;li&gt;Experience designing with scalable and highly available distributed systems in the cloud and on-prem&lt;/li&gt;
&lt;li&gt;Demonstrated ability to work with customers to review complex architecture of existing applications, providing guidance on how to improve by leveraging technology&lt;/li&gt;
&lt;li&gt;Excellent presentation, communication, and interpersonal skills, with the ability to convey complex technical and business concepts in a clear and compelling manner to technology and business leadership&lt;/li&gt;
&lt;li&gt;Ability to strategize with sales teams and provide recommendations on how to drive a multi-threaded account strategy, aligning other MongoDB and ecosystem resources to move towards a mutually beneficial account plan&lt;/li&gt;
&lt;li&gt;The ability to travel up to 25%&lt;/li&gt;
&lt;li&gt;A Bachelor’s degree or equivalent work experience&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;You may also have:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience selling databases and/or deploying applications with any of the major cloud providers&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with database programming and data models&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience in data engineering or AI/ML projects&lt;/li&gt;
&lt;li&gt;Experience in transforming legacy systems and platforms into modern, scalable, and efficient technology stacks&lt;/li&gt;
&lt;li&gt;Understanding of popular sales methodologies/ frameworks such as MEDDPICC/ Command of the Message&lt;/li&gt;
&lt;li&gt;A MongoDB Certification&lt;/li&gt;
&lt;li&gt;A Cloud Provider Certification&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What you do at MongoDB:&lt;/h3&gt;
&lt;p&gt;In this role, you will work on complex opportunities where analysis of situations or data requires an in-depth evaluation of various factors. You will:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design and Architect: Design scalable and performant applications, systems and infrastructure for large software projects leveraging MongoDB&lt;/li&gt;
&lt;li&gt;Customer Advising and Value Articulation: Guide customers on architecture patterns and optimisation strategies for MongoDB, while clearly communicating its business value to the relevant stakeholders&lt;/li&gt;
&lt;li&gt;Sales Partnership: Collaborate with the sales team to drive account success through account planning, opportunity prioritization/qualification and pipeline generation strategy, while taking ownership of the technical aspects (including but not limited to technical discovery, demos, proof of value, presentations, sizing and documentation)&lt;/li&gt;
&lt;li&gt;Demand Generation: Proactively generate demand within the sales territory through self-driven technical initiatives, participation in events such as industry trade shows and account-based marketing events&lt;/li&gt;
&lt;li&gt;Customer Success: Foster strong customer relationships, build champions and ensure customer success and satisfaction&lt;/li&gt;
&lt;li&gt;Innovation and Improvement: Continuously seek opportunities to innovate and improve MongoDB solutions and processes (e.g. by relaying field feedback to the product team), as well as proactively mentor other Solutions Consulting team members&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Personal Training and Development: Engage in ongoing training and professional development to stay abreast of MongoDB product suite as well as industry trends&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What you will learn:&lt;/h3&gt;
&lt;p&gt;MongoDB Product Suite Mastery:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Core Database Server: Master the fundamentals and advanced features of MongoDB&#39;s core database&lt;/li&gt;
&lt;li&gt;Atlas and Advanced Services: Gain expertise in Atlas (fully managed cloud database service), Atlas Stream Processing, Atlas Data Lake, Atlas Full-Text Search, Atlas Vector Search, and Charts&lt;/li&gt;
&lt;li&gt;Relational Migrator: Learn to migrate from relational databases seamlessly&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Market-Relevant Technologies:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Hyperscaler Ecosystem: Gain expertise in designing complex systems utilizing cloud services on hyperscaler platforms&lt;/li&gt;
&lt;li&gt;Complementary Technologies: Enhance your skills with partner and complementary technologies such as Apache Kafka and Kubernetes&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Modern Architecture Design:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design Patterns and Methodologies: Embrace best practices in microservices, DevOps, cloud, and security&lt;/li&gt;
&lt;li&gt;Cutting Edge RAG and AI Architectures: Help customers on their generative AI journeys and working with industry leading partners in the space&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Sales Techniques and Soft Skills:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Effective Communication: Master presentations, demonstrations, and whiteboarding&lt;/li&gt;
&lt;li&gt;Client Interaction: Develop strategies for discovery and objection handling&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Industry Insights:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Diverse Market Verticals: Gain exposure to a broad spectrum of interesting use cases across various industries&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;About MongoDB&lt;/h3&gt;
&lt;p&gt;MongoDB is built for change, empowering our customers and our people to innovate at the speed of the market. We have redefined the data platform for the AI era, enabling builders to create, transform, and disrupt industries with software. MongoDB’s unified data platform, the most widely available, globally distributed data platform on the market, helps organizations modernize legacy workloads, embrace innovation, and unleash AI. Our cloud-native platform, MongoDB Atlas, is the only globally distributed, multi-cloud data platform and is available across AWS, Google Cloud, and Microsoft Azure.&lt;/p&gt;
&lt;p&gt;With offices worldwide and over 67,000 customers, including AI-native startups and approximately 75% of the Fortune 100, relying on MongoDB for their most important applications, we’re powering the next era of software.&lt;/p&gt;
&lt;p&gt;Our compass at MongoDB is our &lt;a href=&quot;https://www.mongodb.com/company&quot;&gt;Leadership Commitment,&lt;/a&gt; guiding how and why we make decisions, show up for each other, and win. It’s what makes us MongoDB.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;To drive the personal growth and business impact of our employees, we’re committed to developing a supportive and enriching culture for everyone. &lt;a href=&quot;https://www.mongodb.com/company/blog/culture/employee-benefits-that-make-a-difference-at-mongodb&quot;&gt;From employee affinity groups, to fertility assistance and a generous parental leave policy&lt;/a&gt;, we value our employees’ wellbeing and want to support them along every step of their professional and personal journeys.&lt;a href=&quot;https://www.mongodb.com/blog/channel/culture&quot;&gt; Learn more about what it’s like to work at MongoDB&lt;/a&gt;, and help us make an impact on the world!&lt;/p&gt;
&lt;p&gt;MongoDB is committed to providing any necessary accommodations for individuals with disabilities within our application and interview process. To request an accommodation due to a disability, please inform your recruiter.&lt;/p&gt;
&lt;p&gt;MongoDB is an equal opportunities employer.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Req ID: 427004&lt;/em&gt;&lt;/p&gt;Find more English Speaking Jobs in Switzerland on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About WPP Media&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP is the trusted growth partner for the world’s leading brands. With exceptional talent, trusted data and intelligence, and world-class partnerships – all united by our pioneering agentic marketing platform, WPP Open – we help clients navigate change, capture opportunity, and deliver transformational growth. &lt;/p&gt;
&lt;p&gt;WPP Media is WPP&#39;s AI-driven media operating unit, bringing together media, data, and partnerships to deliver creative personalisation at scale. Connected through WPP Open and powered by Open Intelligence, clients see exactly where, how, and why their media investment is working.&lt;/p&gt;
&lt;p&gt;For more information, visit &lt;a href=&quot;wppmedia.com&quot;&gt;wppmedia.com&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Ben jij de influencer-goeroe die wij zoeken?&lt;/p&gt;
&lt;p&gt;Volg jij de nieuwste features op Instagram, TikTok, YouTube en Snapchat op de voet? Weet jij precies welke influencers op dit moment hot zijn? Beheers je zowel het Nederlands als het Engels vloeiend? Dan maken we graag kennis met je!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Over WPP Media&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;WPP Media is een dochteronderneming van WPP, het wereldwijde advertisingconglomeraat. We ondersteunen toonaangevende mediabureaus zoals Wavemaker, Mindshare en EssenceMediacom. Binnen WPP Media zijn verschillende centrale activiteiten ondergebracht, waaronder StudioM, Digital Data Hub, Business Intelligence, Proces Management, Marketing Services &amp;amp; Insights, Trading en Quality Management.&lt;/p&gt;
&lt;p&gt;WPP Media is een dynamische, jonge en ambitieuze organisatie met duizenden (young) professionals wereldwijd. In Nederland hebben we kantoren in Amsterdam, Eindhoven en Sittard. Daar werken honderden collega’s voor toonaangevende klanten zoals Action, Lamb Weston, NS, Subway, M&amp;amp;M’s, Brabantia, IKEA en Dr. Oetker.&lt;/p&gt;
&lt;p&gt;Ons kantoor in Amsterdam biedt een adembenemend uitzicht van 180 graden over de stad en de Amstel. De sfeer is informeel en gezellig, met regelmatig vrijdagmiddagborrels in onze skybar op de negende verdieping.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Over StudioM en de functie&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Je gaat aan de slag bij StudioM, ons interne bureau voor influencer marketing. We voeren campagnes uit op grote, vaak internationale schaal. Je werkt met een breed scala aan klanten, influencers en campagnes, waardoor geen dag hetzelfde is.&lt;/p&gt;
&lt;p&gt;In deze rol draag je zelfstandig de operationele verantwoordelijkheid voor complexe en omvangrijke projecten. Denk aan multi-marketprojecten, strategische accounts, campagnes voor meerdere merken en innovatieve trajecten.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Wat ga je doen?&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Projectmanagement: Je bent zelfstandig verantwoordelijk voor het opzetten, uitvoeren en coördineren van influencer marketingcampagnes.&lt;/li&gt;
&lt;li&gt;Planning en voortgang: Je stuurt de dagelijkse uitvoering aan, maakt duidelijke projectplanningen en bewaakt deadlines, afhankelijkheden, prioriteiten en de voortgang van projecten.&lt;/li&gt;
&lt;li&gt;Influencerselectie en briefings: Je vertaalt de kaders en briefings van de accountmanager naar concrete selectielijsten, taken en creatieve briefings, waaronder influencerbriefings. Waar nodig verdeel je taken onder junior collega’s of stagiairs.&lt;/li&gt;
&lt;li&gt;Relatiebeheer en onderhandelingen: Je onderhoudt relaties met influencers en talentbureaus en onderhandelt zelfstandig over marktconforme vergoedingen binnen het vastgestelde budget.&lt;/li&gt;
&lt;li&gt;Budgetbeheer en administratie: Je beheert projectbudgetten en houdt kosten bij, zoals influencer fees, buy-outs en event- en productiekosten. Ook verzorg je contracten en regel je boekingen met bureaus.&lt;/li&gt;
&lt;li&gt;Content en kwaliteit: Je bewaakt de voortgang en kwaliteit van alle content en deliverables, voert eerste contentchecks uit en werkt nauw samen met accountmanagers richting definitieve goedkeuring.&lt;/li&gt;
&lt;li&gt;Afstemming en rapportage: Je werkt samen met interne teams om effectieve campagnes te realiseren. Je houdt klanten, stakeholders en de accountmanager proactief op de hoogte van de dagelijkse voortgang, sluit waar nodig aan bij klantupdates en rapporteert over resultaten en aandachtspunten.&lt;/li&gt;
&lt;li&gt;Risicobeheersing en optimalisatie: Je signaleert risico’s, knelpunten en optimalisatiemogelijkheden, bespreekt deze met de (senior) accountmanager en escaleert tijdig waar nodig. Je stuurt actief bij, optimaliseert lopende campagnes en voert verbeteringen door met medior- en juniorcollega’s.&lt;/li&gt;
&lt;li&gt;Evaluatie en begeleiding: Je levert inhoudelijke input voor projectevaluaties, vertaalt learnings naar verbeteringen voor toekomstige campagnes en begeleidt en werkt stagiairs in binnen het team.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Wat breng je mee?&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Je hebt een passie voor influencer marketing en leeft social media. Je kijkt liever YouTube en TikTok dan televisie en denkt in Instagram Stories.&lt;/li&gt;
&lt;li&gt;Je volgt de nieuwste features en ontwikkelingen op socialmediaplatformen en weet welke influencers op dit moment relevant zijn.&lt;/li&gt;
&lt;li&gt;Je begrijpt hoe platformen als Facebook, Instagram, YouTube, TikTok en Snapchat werken en houdt hun innovaties bij.&lt;/li&gt;
&lt;li&gt;Je bent creatief, maar werkt ook gestructureerd en gecoördineerd.&lt;/li&gt;
&lt;li&gt;Je beheerst het Nederlands en Engels vloeiend.&lt;/li&gt;
&lt;li&gt;5+ jaar ervaring&lt;/li&gt;
&lt;li&gt;Je bent hands-on en zorgt ervoor dat campagnes tot in de puntjes geregeld zijn.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Wat bieden wij?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Een boeiende baan in een vooruitstrevend en informeel team binnen een van de grootste communicatiegroepen ter wereld. Je krijgt de mogelijkheid om je talenten verder te ontwikkelen in een inspirerende werkomgeving. En natuurlijk werk je met fijne collega’s in ons geweldige kantoor, die iedere werkdag bijzonder maken.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Salaris: €3.800 - €5.800&lt;/strong&gt;&amp;nbsp;(op basis van 38,75 uur per week).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Toegang tot M Academy:&lt;/strong&gt;&amp;nbsp;Voor uitgebreide trainingen en workshops in zowel hard als soft skills, inclusief specifieke AI-trainingen.&lt;/li&gt;
&lt;li&gt;Werken voor grote (internationale) merken en klanten.&lt;/li&gt;
&lt;li&gt;Een zelfstandige rol met veel vrijheid.&lt;/li&gt;
&lt;li&gt;De kans om een breder perspectief binnen influencer marketing en social media te ontwikkelen en kennis vanuit de wereld van mediabureaus op te doen.&lt;/li&gt;
&lt;li&gt;Werken binnen een energiek, ambitieus en gezellig team met focus op AI-transformatie.&lt;/li&gt;
&lt;li&gt;Open communicatie en een fijne werksfeer waarin iedereen zichzelf kan zijn.&lt;/li&gt;
&lt;li&gt;Goede arbeidsvoorwaarden en ontwikkelmogelijkheden.&lt;/li&gt;
&lt;li&gt;Een fijne kantoorplek op een mooie locatie in Amsterdam (Rivierenbuurt);&lt;/li&gt;
&lt;li&gt;Een team met veel kennis, kunde en gezelligheid;&lt;/li&gt;
&lt;li&gt;Vrijdagmiddag borrels en events op onze rooftop aan de Amstel&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Mental Wellbeing:&lt;/strong&gt; Toegang tot ons well being platform Telus&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Reiskostenvergoeding:&lt;/strong&gt; Reiskosten worden volledig vergoed.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;8% vakantiegeld en 26 vakantiedagen per jaar&lt;/strong&gt; (plus 9 extra bij te kopen!).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Hybrid Working allowance:&lt;/strong&gt; €30 netto per maand bij fulltime.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Bring Your Own Device (BYOD):&lt;/strong&gt;&amp;nbsp;Je ontvangt een maandelijkse telefoonvergoeding van €57,50 netto.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Klaar voor de volgende stap in je carrière?&lt;/p&gt;
&lt;p&gt;Solliciteer nu en word onderdeel van ons ambitieuze team!&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;Please read our &lt;a href=&quot;https://www.wppmedia.com/pages/privacy-policy#:~:text=WPP%20Media%20Privacy%20Notice%20for%20Recruitment&quot;&gt;Privacy Notice&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;for more information on how we process the information you provide.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW227196529 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;Find more English Speaking Jobs in Netherlands on Arbeitnow

&lt;p&gt;&lt;/p&gt;
&lt;h2 data-pm-slice=&quot;1 3 []&quot;&gt;In a nutshell&lt;/h2&gt;
&lt;p&gt;&lt;/p&gt;
&lt;p&gt;We’re looking for a technically skilled and creatively driven Video Editor Working Student. Your primary focus will be the post-production of our employer branding organic social content, acting as the final touch that ensures every video is engaging through dynamic editing and recognizable as Picnic at a glance.&lt;/p&gt;
&lt;p&gt;You’ll collaborate with a diverse team of campaign and event managers, supported by designers and the wider recruitment team of 30+ colleagues. Together, you’ll create high-impact work that doesn’t just sit in a folder. Our campaigns are the heart of our employer brand; convincing quality talent to join the ride.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Tricks of the trade&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Video Editing: &lt;/strong&gt;Take raw footage and turn it into engaging content for LinkedIn and Instagram.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Set Prep &amp;amp; Shooting&lt;/strong&gt;: Support the team during shoots and directing non-professional subjects.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Motion Graphics:&lt;/strong&gt; A plus if you know the basics of motion graphics.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Color Grading &amp;amp; Branding:&lt;/strong&gt; Use your eye for detail to ensure all video assets are aligned, of high quality, and follow the branding guidelines.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Your superpowers&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;You are currently pursuing a study in a creative field (e.g. Media studies or similar).&lt;/li&gt;
&lt;li&gt;You are a strong short-form editor: hooks, retention editing, colour grading, sound design, and a sense of music and tempo.&lt;/li&gt;
&lt;li&gt;You are comfortable shooting content with both a smartphone and a camera, with a good eye for framing, lighting, and composition.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You understand color theory and have experience with editing and color grading software (Adobe Suite and CapCut).&lt;/li&gt;
&lt;li&gt;You think in &quot;systems&quot; and understand how to build project files that can be easily adapted to different platforms.&lt;/li&gt;
&lt;li&gt;Bonus: you have working knowledge of After Effects to adjust animations and graphics, as well as photography skills.&lt;/li&gt;
&lt;li&gt;Fluent in English (Dutch, French or German are a plus!)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Picnic perks&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;🚀&lt;strong&gt;Every expert was once a beginner!&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;You’ll get plenty of opportunities to challenge yourself and grow, including Lunch &amp;amp; Learn sessions, and tailored soft skills training.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;🌍&lt;strong&gt;Make a difference&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;You’ll work in an awesome startup environment with the freedom to drive your own projects and create a visible impact. Our fully electric vehicles and sustainable business model mean you’ll also be contributing to making the world a better place!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;🤝&lt;strong&gt;Teamwork makes the dream work&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;With more than 80 nationalities across 3 countries, you’ll be part of a diverse company with plenty of cool stuff to get involved with, from board game evenings to after-work drinks to our company ski trip and more!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🥗Fresh Lunch, coffee, and snacks&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our offices are equipped with fully-fledged coffee bars and a kitchen and chefs. They prepare delicious fresh and warm lunches every day so you can keep your energy up.&lt;/p&gt;
&lt;p&gt;💪&lt;strong&gt;Stay healthy&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;Mental health is important. As well as having the option to speak with Picnic colleagues who act as confidential advisors, our collaboration with OpenUp gives you easy access to professional psychologists, along with workshops and materials.&lt;br&gt;There are plenty of sports communities and events to get involved with, from tennis to yoga to climbing!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;💰&lt;strong&gt;Attractive package&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You’ll receive a gross hourly wage of €16.75, along with a laptop to support your work. Travel costs can also be reimbursed, depending on your location.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;Find Jobs in Netherlands on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About Nebius:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nebius is leading a new era in cloud infrastructure for the global AI economy. We are building a full-stack AI cloud platform that supports developers and enterprises from data and model training through to production deployment, without the cost and complexity of building large in-house AI/ML infrastructure.&lt;/p&gt;
&lt;p&gt;Built by engineers, for engineers. From large-scale GPU orchestration to inference optimization, we own the hard problems across compute, storage, networking and applied AI.&lt;/p&gt;
&lt;p&gt;Listed on Nasdaq (NBIS) and headquartered in Amsterdam, we have a global footprint with R&amp;amp;D hubs across Europe, the UK, North America and Israel. Our team of 1,500+ includes hundreds of engineers with deep expertise across hardware, software and AI R&amp;amp;D.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;#LI-IV1&lt;/span&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;br&gt;&lt;br&gt;The role&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;div id=&quot;content&quot; class=&quot;highlighter-context page view&quot; data-inline-comments-target=&quot;true&quot; data-remix-main-content=&quot;true&quot; data-testid=&quot;page-content-only&quot;&gt;
&lt;div class=&quot;_30huDKYbGa _24h04i2Njc _034jHtYbGa _313842dnbC _0adFHsIZbP _1DCdHiyFLW _2XsHFMIZbP _39xV02N91d&quot;&gt;
&lt;div&gt;
&lt;div id=&quot;main-content&quot; class=&quot;wiki-content css-1i5i0uk e5xcnr80&quot; data-testid=&quot;pageContentRendererTestId&quot; data-vc=&quot;pageContentRendererTestId&quot; data-test-appearance=&quot;full-page&quot;&gt;
&lt;div class=&quot;renderer-overrides&quot;&gt;
&lt;div class=&quot;css-3qfej8&quot;&gt;
&lt;div class=&quot;ak-renderer-wrapper is-full-page css-pw7jst&quot;&gt;
&lt;div class=&quot;css-11mnq1u&quot;&gt;
&lt;div class=&quot;ak-renderer-document&quot;&gt;
&lt;p data-renderer-start-pos=&quot;187&quot; data-local-id=&quot;6f66b3304019&quot;&gt;The Service Desk IT Operations Lead is the senior individual contributor on the Service Desk path and the senior technical escalation point for Service Desk across &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;EMEA&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;APAC&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;. The role owns and improves Service Desk processes, runbooks, escalation paths, the employee hardware lifecycle and new-hire IT onboarding, administers Service Desk tooling on behalf of its owners, and leads improvement initiatives and cross-functional projects. It acts as the bridge between the Service Desk and Infrastructure, Enterprise Applications and Security, and leads through expertise, judgment and influence rather than formal authority. It carries no line-management responsibility.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;879&quot; data-local-id=&quot;c645114533a9&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Your responsibilities will include:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;11be38ca981c&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;903&quot; data-local-id=&quot;38d58248e3b1&quot;&gt;Serve as the final technical escalation point within Service Desk for high-severity, high-complexity and business-critical issues, before engagement of Infrastructure, Enterprise Applications, Security or vendors; coordinate major-incident response, communication and post-incident follow-through with the relevant teams.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1228&quot; data-local-id=&quot;d7a0b85de128&quot;&gt;Act as consultation point for L1/L2 on complex or unusual cases: advise on troubleshooting approach, ownership, escalation path and resolution before issues are escalated.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1403&quot; data-local-id=&quot;79197ef3d5ff&quot;&gt;Act as subject matter expert for the end-user computing environment: endpoints (Windows, macOS), mobile devices, identity and access (Entra ID / Active Directory, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;SSO&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;MFA&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;), Microsoft 365, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;MDM&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;, collaboration tools and meeting-room technology.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;1649&quot; data-local-id=&quot;373bb2e063e6&quot;&gt;Administer and configure Service Desk tooling (e.g. Jira Service Management workflows and automation, device enrolment and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;MDM&lt;/span&gt; policy, hardware asset management tooling) as agreed with the tool and platform owners, and propose and implement improvements, including request workflows and automations used by adjacent functions. Ownership of the tools and platforms sits with IT leadership and platform owners.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2061&quot; data-local-id=&quot;d1c8fe9e90b1&quot;&gt;Administer selected corporate IT systems and services according to operational requirements, including access and permissions management, service configuration and automation.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2240&quot; data-local-id=&quot;1bff032a414c&quot;&gt;Maintain and improve Service Desk procedures, runbooks, escalation paths and knowledge base; propose technical standards for approval by Service Desk management and maintain them once approved; advise on operational priorities.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2471&quot; data-local-id=&quot;eef532dfc55a&quot;&gt;Contribute to creating and updating documentation: runbooks, process documents, technical standards and knowledge-base articles, setting the standard for documentation quality across the team.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2667&quot; data-local-id=&quot;31771b1a2e51&quot;&gt;Analyze ticket, escalation and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;SLA&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; data to identify systemic issues and contribute to &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;SLA&lt;/span&gt; reporting; lead root-cause analysis and problem management; design process, tooling and automation changes that improve first-time resolution and reduce escalation volume.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;2932&quot; data-local-id=&quot;7677c9383a4b&quot;&gt;Assess proposed solutions and operational changes for supportability and user impact; advise management and partner teams on the support implications of technology decisions.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3110&quot; data-local-id=&quot;0def3a568ed8&quot;&gt;Provide organizational context on existing and legacy IT processes, systems, decisions and ownership structures; apply it when evaluating current processes, and improve legacy practices where appropriate.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3318&quot; data-local-id=&quot;62eadc8a8a51&quot;&gt;Identify gaps or ambiguities in operational ownership and work with the relevant stakeholders to establish practical solutions.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3449&quot; data-local-id=&quot;bd51ed379576&quot;&gt;Own and improve employee-lifecycle processes, including hardware provisioning and, with Onboarding and People teams, new-hire IT onboarding across &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;EMEA&lt;/span&gt; and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;APAC&lt;/span&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3614&quot; data-local-id=&quot;2e52d4fe01ee&quot;&gt;Recommend standards for company-provided laptops, peripherals and other end-user equipment, balancing business need, supportability, lifecycle and market availability; maintain the approved standards.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3818&quot; data-local-id=&quot;c12e6b0be08d&quot;&gt;Own employee hardware lifecycle processes, provisioning, replacement, reuse, return, disposal and employee resale, and provide demand forecasts and regional requirements (including Bill &amp;amp; Hold) to IT Supply Chain and Procurement; recommend routine purchases against agreed standards, approving only within a documented delegated spend limit.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4163&quot; data-local-id=&quot;2a1e527f3510&quot;&gt;Lead and continuously improve equipment reuse and employee resale, including TechShop.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4253&quot; data-local-id=&quot;74b8adaf4413&quot;&gt;Contribute to forecasting and budget planning for employee technology and Service Desk requirements.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4357&quot; data-local-id=&quot;8f5235a54054&quot;&gt;Support Service Desk contracts, renewals and licensing; maintain working relationships with hardware and Service Desk vendors.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4487&quot; data-local-id=&quot;e9d102a5cacb&quot;&gt;Lead Service Desk projects, system migrations, new technology rollouts, process optimization, and contribute Service Desk expertise to company initiatives such as regional expansion, office launches, organizational changes and onboarding improvements, working with Infrastructure, Enterprise Applications, Security, HR/People, Onboarding, Recruiting, Procurement, Workplace/Facilities and the &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;AV&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;/Builds team.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4899&quot; data-local-id=&quot;91bc1761e199&quot;&gt;Advise partner functions on Service Desk capabilities, procedures, requirements and dependencies, and work with them to define and improve shared operational processes (e.g. joiner/mover/leaver with People, office launches with Workplace).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5142&quot; data-local-id=&quot;285e80a6e3d0&quot;&gt;Act as technical interviewer in Service Desk recruitment, providing structured feedback and hiring recommendations to management, and technical input to role requirements.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5317&quot; data-local-id=&quot;9780204b4ad7&quot;&gt;Deliver technical onboarding for new team members and mentor L1 and L2 through joint troubleshooting, coaching and knowledge transfer, documenting approaches to reduce reliance on individual knowledge.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5522&quot; data-local-id=&quot;772b15110e33&quot;&gt;Stay hands-on: support the IT Bar, queue and events alongside L1/L2 when needed, and lead by example on ticket quality and communication.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5663&quot; data-local-id=&quot;146b9f785354&quot;&gt;Provide operational evidence for audits and compliance (including equipment lifecycle and offboarding); follow security, access-governance and procurement requirements; escalate material concerns to the appropriate owner.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;5888&quot; data-local-id=&quot;eb5024856e6e&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;We expect you to have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;7e5ce408e854&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5906&quot; data-local-id=&quot;2e0134fc5cec&quot;&gt;Bachelor’s degree in Information Technology or related field, or equivalent experience.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5997&quot; data-local-id=&quot;fd1086625afb&quot;&gt;5+ years of IT support or service desk experience with demonstrated progression in responsibility.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6099&quot; data-local-id=&quot;a5533bb5485f&quot;&gt;Advanced technical certifications (Microsoft 365, Azure, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;ITIL&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; Intermediate, Security+, etc.) strongly preferred.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6215&quot; data-local-id=&quot;70d931eb497a&quot;&gt;Deep knowledge of enterprise IT systems, networks, and security practices.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6293&quot; data-local-id=&quot;1d671d9661d5&quot;&gt;Strong leadership, coaching, and collaboration skills.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6351&quot; data-local-id=&quot;68035fbe2ddf&quot;&gt;Proven ability to manage high-priority incidents and lead cross-functional troubleshooting efforts.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;6454&quot; data-local-id=&quot;42e1ed1ec464&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Related Competencies&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;4c2a8c3a1840&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6478&quot; data-local-id=&quot;1d7c477c3408&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Knowledge &amp;amp; Skills&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;c6442bb30dcf&quot; data-indent-level=&quot;2&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6500&quot; data-local-id=&quot;6201abdc4e57&quot;&gt;Recognised expert in end-user computing and support operations, with breadth across endpoints, identity, collaboration, device management and security touch points.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;6666&quot; data-local-id=&quot;4de70e5501b9&quot;&gt;Diagnoses ambiguous, cross-platform issues; experienced in root-cause analysis and process optimisation.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;6772&quot; data-local-id=&quot;38a9483e5624&quot;&gt;Translates complex issues into clear guidance for technical and non-technical audiences.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6866&quot; data-local-id=&quot;9b59c05ded59&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Autonomy&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;f3fa01dee386&quot; data-indent-level=&quot;2&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;6878&quot; data-local-id=&quot;ac00d8c8e653&quot;&gt;Operates with a high degree of independence and trusted judgment.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;6945&quot; data-local-id=&quot;e42c3ba8fbc1&quot;&gt;Takes the most sensitive escalations from intake to follow-up.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7009&quot; data-local-id=&quot;b6840c2e8198&quot;&gt;Independently identifies improvements and drives them to completion; proactively pitches projects within the Service Desk domain.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7140&quot; data-local-id=&quot;39901a9d8022&quot;&gt;Advises management and partner teams on the support implications of technology decisions. Significant spend, strategic or organisational changes, and decisions outside delegated authority are aligned with management.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;7362&quot; data-local-id=&quot;341f063d921e&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Complexity&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;d58f21e1a04e&quot; data-indent-level=&quot;2&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;7376&quot; data-local-id=&quot;87a34b97b2e5&quot;&gt;Handles the most complex technical and operational problems in the support function: multiple systems, conflicting signals, incomplete data, elevated business risk.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7542&quot; data-local-id=&quot;7519827d535a&quot;&gt;Leads escalations, often coordinating multiple IT functions.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7604&quot; data-local-id=&quot;b392b04da178&quot;&gt;Designs and improves workflows and procedures where no precedent exists.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;7682&quot; data-local-id=&quot;0cd98d0a9ee2&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Impact&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;dd92537953a7&quot; data-indent-level=&quot;2&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;7692&quot; data-local-id=&quot;949bd1de2fa4&quot;&gt;Broad impact on service reliability, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;SLA&lt;/span&gt; performance, support maturity and user experience across &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;EMEA&lt;/span&gt; and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;APAC&lt;/span&gt;.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7806&quot; data-local-id=&quot;ebc6e83a03aa&quot;&gt;Reduces downtime, repeat incidents and escalation volume.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7865&quot; data-local-id=&quot;2a3af78999d8&quot;&gt;Shapes employee technology from onboarding through equipment return; ensures knowledge transfer and team readiness.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;7986&quot; data-local-id=&quot;18bfc1baa982&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;People / Leadership&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;cb1823164d80&quot; data-indent-level=&quot;2&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8009&quot; data-local-id=&quot;351c1bc9af51&quot;&gt;Leads through expertise, coordination and example, not formal authority.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;8083&quot; data-local-id=&quot;e6de89a1c31a&quot;&gt;Escalation point and mentor for L1 and L2; shapes team capability over time. Technical interviewer.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;8184&quot; data-local-id=&quot;807a11f2b56f&quot;&gt;No line management: hiring decisions, performance, compensation and other people-management accountabilities sit with Service Desk management.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
