&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la délégation des tâches, la gestion de la charge de travail, la formation et le développement des membres de l’équipe.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
