&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We offer a competitive, people-first benefits package designed to support every aspect of your life:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:100,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Job bullet&quot;&gt;Core Benefits: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Job bullet&quot;&gt;Discretionary bonus, competitive pension, health insurance, life insurance and critical illness cover.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
