&lt;h3&gt;&lt;span style=&quot;color: rgb(222, 220, 0);&quot;&gt;&lt;strong&gt;WIE DU UNS BEGEISTERST&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul data-editing-info=&quot;{&amp;quot;applyListStyleFromLevel&amp;quot;:true}&quot;&gt;
&lt;li&gt;
&lt;div data-olk-copy-source=&quot;MessageBody&quot;&gt;Abgeschlossenes Studium der Betriebswirtschaftslehre, idealerweise ergänzt durch Erfahrung in der Wirtschaftsprüfung&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
