&lt;div class=&quot;entry-intro&quot;&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;iframe src=&quot;https://www.youtube.com/embed/YRy3terxHIg&quot; width=&quot;560&quot; height=&quot;315&quot;&gt;&lt;/iframe&gt;&lt;/span&gt;&lt;/p&gt;
